"""Render v2 registry → generated files. views/registry.json is the one source; never edit the outputs by hand.
Writes: views/library.json (LibrarySpec of the components that ship: what views.js draws and vendor/openui-lang.mjs reads),
views/prompt/all.md + views/prompt/<recipe>.md (the view-writing prompt, full and per recipe subset), views/checkers.json
(gate steps, per-component checker, marks, caps) and the block between the views markers in SCHEMA.md (tables + the
<!-- schema: views --> JSON Schema for an item's views[]).
Fails (and --check fails) on: a broken ref; a shipping engine tool engine/ does not serve, or one it serves the registry lacks;
a banned prop name (look props, F3); answer/key anywhere but Predict.answer, which must be a required key reference (F5); a string prop with no maxLength or a list with no maxItems (F2, F7).
usage: python3 tools/gen_views.py [--check]   (--check: write nothing, exit 1 if any output is stale)"""
import json
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
REG = os.path.join(ROOT, "views", "registry.json")
SCHEMA_MD = os.path.join(ROOT, "SCHEMA.md")
BEGIN = "<!-- views:begin (generated by tools/gen_views.py from views/registry.json; do not edit) -->"
END = "<!-- views:end -->"
STAGES = {"pre", "wrong", "post"}


def load(path=REG):
    with open(path) as f:
        return json.load(f)


def tools(reg, live_only=False):
    """{tool: ships} for every engine tool."""
    return {t: e["ships"] for e in reg["engines"].values() if not (live_only and e["ships"] == "planned") for t in e["tools"]}


def shipped(reg):
    """Components that ship (drawn by the renderer) and whose checker, if any, ships too. Registry order. Staged ones (reg.staged) do not."""
    live, wait = tools(reg, live_only=True), ("planned", *reg.get("staged", {}))
    return [n for n, c in reg["components"].items() if c["ships"] not in wait and c.get("checker") in (None, *live)]


def staged(reg):
    """Components whose ships tag is a staged one (reg.staged): contract locked, the drawing still in flight. Registry order."""
    return [n for n, c in reg["components"].items() if c["ships"] in reg.get("staged", {})]


def pool(reg):
    """What the gate's catalog and a staged recipe's prompt may name: shipped + staged, registry order."""
    ok = set(shipped(reg)) | set(staged(reg))
    return [n for n in reg["components"] if n in ok]


def engine_tools():
    """Tool names engine/ serves (P0.3), or None when the package is not importable."""
    sys.path.insert(0, ROOT)
    try:
        import engine
    except ImportError:
        return None
    return {t["name"] for t in engine.spec()}


def schema_problems(reg, where, s):
    """Caps (F2, F7) and refs inside one prop schema."""
    out = []
    if s.get("type") == "string" and "maxLength" not in s and "enum" not in s and "x-enum" not in s:
        out.append(f"{where}: string with no maxLength")
    if s.get("type") == "array":
        if "maxItems" not in s:
            out.append(f"{where}: list with no maxItems")
        out += schema_problems(reg, where + "[]", s.get("items", {}))
    for ref in [s.get("$ref", ""), *(x.get("$ref", "") for x in s.get("anyOf", []))]:
        if ref and ref.removeprefix("#/$defs/") not in reg["components"]:
            out.append(f"{where}: $ref {ref} is no component")
    if "x-enum" in s and not isinstance(reg.get(s["x-enum"]), list):
        out.append(f"{where}: x-enum {s['x-enum']} is no registry list")
    return out


def problems(reg, served=None):
    """Every broken rule in the registry, as text lines (empty = good). served = engine tool names (None = skip)."""
    out, comps, all_tools = [], reg["components"], tools(reg)
    if served is not None:
        live = set(tools(reg, live_only=True))
        out += [f"tool {t}: ships in the registry but engine/ has no such tool" for t in sorted(live - served)]
        out += [f"tool {t}: engine/ serves it but the registry does not list it" for t in sorted(served - set(all_tools))]
    ok = set(shipped(reg))
    for name in [reg["root"], *reg["base"]]:
        if name not in ok:
            out.append(f"root/base: {name} is no shipping component")
    for name, c in comps.items():
        if c["ships"] != "planned" and c["ships"] not in reg.get("staged", {}) and not re.fullmatch(r"P\d+\.\d+", c["ships"]):
            out.append(f"{name}: unknown ships {c['ships']}")
        if c["layer"] not in reg["layers"]:
            out.append(f"{name}: unknown layer {c['layer']}")
        if c["kind"] not in ("layout", "domain", "interaction"):
            out.append(f"{name}: unknown kind {c['kind']}")
        if c.get("checker") is not None and c["checker"] not in all_tools:
            out.append(f"{name}: checker {c['checker']} is no engine tool")
        if c["layer"] == "L2" and "checker" not in c:
            out.append(f"{name}: L2 component needs a checker")
        for r in c["required"]:
            if r not in c["props"]:
                out.append(f"{name}: required {r} is no prop")
        for p, s in c["props"].items():
            if p in reg["banned_props"]:
                out.append(f"{name}.{p}: banned prop name (look = CSS by cascade, F3)")
            if p in reg["key_props"] and f"{name}.{p}" not in reg["key_ref_props"]:
                out.append(f"{name}.{p}: banned prop name (only {', '.join(reg['key_ref_props'])} may name the answer, F5)")
            if f"{name}.{p}" in reg["key_ref_props"] and (s.get("pattern") != reg["key_ref"] or p not in c["required"]):
                out.append(f"{name}.{p}: must be a required key reference (pattern {reg['key_ref']}), never a literal (F5)")
            out += schema_problems(reg, f"{name}.{p}", s)
        for p, n in c.get("cluck", {}).items():
            if p not in ("rows", "cols"):
                out.append(f"{name}: cluck caps are rows / cols")
    for t in all_tools:
        if not re.fullmatch(r"[a-z]+\.[a-z_]+", t):
            out.append(f"tool {t}: want capability.name")
    for engine, e in reg["engines"].items():
        for t in e["tools"]:
            if not t.startswith(engine + "."):
                out.append(f"tool {t}: not under engine {engine}")
    for r, rec in reg["recipes"].items():
        for name in rec["components"]:
            if name not in comps:
                out.append(f"recipe {r}: unknown component {name}")
        if not rec["stages"] or set(rec["stages"]) - STAGES:
            out.append(f"recipe {r}: stages must be a non-empty subset of {sorted(STAGES)}")
        if rec["length"] not in ("S", "M"):
            out.append(f"recipe {r}: length S or M")
        for k, v in [("rules", rec.get("rules")), ("example", rec.get("example")), *((f"notes.{n}", x) for n, x in rec.get("notes", {}).items())]:
            if v is not None and not (isinstance(v, list) and all(isinstance(x, str) for x in v)):
                out.append(f"recipe {r}: {k} must be a list of lines")
    for ref, d in reg["refs"].items():
        if set(d["stages"]) - STAGES:
            out.append(f"ref {ref}: bad stage")
    return out


DROP = object()   # expand(): a schema that names only components outside the pool (its prop is left out of that view)


def expand(reg, s, pool=None):
    """A registry prop schema → plain JSON Schema: x-any = any shipping component, x-enum = a registry list. pool = the component
    names this view may name (default: shipped); a $ref outside it is dropped (an anyOf keeps the rest, one left = that $ref)."""
    pool = set(shipped(reg)) if pool is None else set(pool)
    if isinstance(s, list):
        return [x for x in (expand(reg, v, pool) for v in s) if x is not DROP]
    if not isinstance(s, dict):
        return s
    if s.get("x-any"):
        return {"anyOf": [{"$ref": f"#/$defs/{n}"} for n in shipped(reg)]}
    if "$ref" in s and s["$ref"].removeprefix("#/$defs/") not in pool:
        return DROP
    out = {}
    for k, v in s.items():
        if k == "x-enum":
            continue
        x = expand(reg, v, pool)
        if x is not DROP:
            out[k] = x
    if "items" in s and "items" not in out:
        return DROP
    if "anyOf" in s:
        if not out["anyOf"]:
            return DROP
        if len(out["anyOf"]) == 1:
            return out["anyOf"][0]
    if "x-enum" in s:
        out["enum"] = reg[s["x-enum"]]
    return out


def ts(s, caps=False, every=None):
    """A prop schema as a signature type (the vendored prompt generator's spelling); caps=True adds ≤N. An anyOf of every shipping
    component (x-any; every = their count) is "Component", a shorter anyOf the union "A | B" ("(A | B)[]" as list items)."""
    if "enum" in s:
        return " | ".join(f'"{v}"' for v in s["enum"])
    if "$ref" in s:
        return s["$ref"].removeprefix("#/$defs/")
    if caps and s.get("pattern", "").startswith("^key\\."):
        return "key.<id>"
    if "anyOf" in s:
        names = [x.get("$ref", "").removeprefix("#/$defs/") for x in s["anyOf"]]
        return "Component" if every is None or len(names) >= every or not all(names) else " | ".join(names)
    t = s.get("type")
    if t == "array":
        item = ts(s["items"], caps, every) if "items" in s else "any"
        item = f"({item})" if " | " in item and "anyOf" in s.get("items", {}) else item
        return item + "[]" + (f"≤{s['maxItems']}" if caps and "maxItems" in s else "")
    if t == "string" and caps and "maxLength" in s:
        return f"string≤{s['maxLength']}"
    return {"integer": "number", None: "any"}.get(t, t)


def sig(reg, name, caps=False, pool=None):
    c, every = reg["components"][name], len(shipped(reg))
    props = [(p, expand(reg, s, pool)) for p, s in c["props"].items()]
    return f"{name}(" + ", ".join(p + ("" if p in c["required"] else "?") + ": " + ts(x, caps, every) for p, x in props if x is not DROP) + ")"


def _spec(reg, name, names):
    """one component's LibrarySpec entry (signature, description, layer, kind, props) and $defs entry, naming only `names`"""
    c = reg["components"][name]
    ex = expand(reg, c["props"], names)
    props = {"type": "object", "properties": ex, "required": [r for r in c["required"] if r in ex]}
    return ({"signature": sig(reg, name, pool=names), "description": c["desc"], "layer": c["layer"], "kind": c["kind"], "props": props},
            {"description": c["desc"], **props})


def library(reg):
    """LibrarySpec JSON of the shipping components, read by vendor/openui-lang.mjs (createParser(schema, root),
    generateSystemPrompt({library}): components[].signature under componentGroups) and by views-lib.js (components[].props)."""
    names = shipped(reg)
    defs, comps = {}, {}
    for name in names:
        comps[name], defs[name] = _spec(reg, name, names)
    groups = [{"name": layer, "notes": [note], "components": [n for n in names if reg["components"][n]["layer"] == layer]}
              for layer, note in reg["layers"].items()]
    out = {"id": "stem", "version": reg["version"], "root": reg["root"], "schema": {"$defs": defs}, "components": comps,
           "componentGroups": [g for g in groups if g["components"]], "marks": reg["marks"]}
    if staged(reg):   # contract locked, drawing in flight: the gate's catalog (views_gate.catalog) reads staged.schema
        full = pool(reg)
        specs = {n: _spec(reg, n, full) for n in full}
        out["staged"] = {"note": "; ".join(reg["staged"].values()), "components": {n: specs[n][0] for n in staged(reg)},
                         "schema": {"$defs": {n: specs[n][1] for n in full}}}
    return out


def prompt(reg, recipe=None):
    rec = reg["recipes"].get(recipe) if recipe else None
    ok = shipped(reg) if rec is None or not set(rec["components"]) & set(staged(reg)) else pool(reg)
    names = ok if rec is None else [n for n in dict.fromkeys([*reg["base"], *rec["components"]]) if n in ok]
    stages = rec["stages"] if rec else sorted(STAGES, key=["pre", "wrong", "post"].index)
    lines = [f"# View prompt: {'all components' if rec is None else 'recipe ' + recipe} (library {reg['version']}, profile {reg['profile']})",
             "Generated by tools/gen_views.py from views/registry.json. Do not edit.", ""]
    if rec:
        lines += [f"Recipe: {rec['desc']}. Length {rec['length']}. Stages: {', '.join(stages)}.", ""]
    lines += ["## Language (OpenUI Lang, profile stem)",
              f"- One statement per line: `name = Component(arg, ...)`, args in the order shown. The tree hangs off `root = {reg['root']}([...])`.",
              "- Forward refs are fine. `$name = value` declares state.",
              "- `q = Query(\"tool\", {args}, {defaults})` asks an engine (server side). Never type a value an engine can compute.",
              "- No Mutation, no Action, no navigation, no timers.",
              "- The site draws every look. Never describe colours or sizes. State words are marks only: " + ", ".join(reg["marks"]) + ".",
              "- Caps: `string≤N` = at most N characters, `[]≤N` = at most N items. Over a cap the statement is dropped.",
              "- Nothing fits? Draw a `Doodle`. Never send a view with no visual.", "",
              "## Bank refs"]
    for ref, d in reg["refs"].items():
        here = ", ".join(s for s in d["stages"] if s in stages)
        server = d.get("server_props")
        if server and server.split(".")[0] in names:
            here = (here + "; " if here else "none here, except ") + f"as the {server} reference in any stage (the server resolves it, F5)"
        lines.append(f"- `{ref}.*`: {d['desc']}. Stages: {here or 'none here, never use'}.")
    lines += ["", "## Engine tools (Query)"] + [f"- `{t}`" for t in tools(reg, live_only=True)]
    lines += ["", "## Components (`?` = optional)"]
    for layer, note in reg["layers"].items():
        here = [n for n in names if reg["components"][n]["layer"] == layer]
        if here:
            lines += [f"### {layer}: {note}"] + [f"- `{sig(reg, n, caps=True, pool=ok)}`: {reg['components'][n]['desc']}" for n in here]
    if rec and rec.get("rules"):
        lines += ["", "## Scene rules"] + [f"- {x}" for x in rec["rules"]]
    for subject, notes in (rec or {}).get("notes", {}).items():
        lines += ["", f"## Notes: {subject}"] + [f"- {x}" for x in notes]
    if rec and rec.get("example"):
        lines += ["", "## Example", "```", *rec["example"], "```"]
    return "\n".join(lines) + "\n"


def checkers(reg):
    live = tools(reg)
    return {"version": reg["version"], "gate": reg["gate"],
            "components": [{"component": n, "checker": c["checker"], "ships": live[c["checker"]]}
                           for n, c in reg["components"].items() if "checker" in c],
            "refs": {ref: d["stages"] for ref, d in reg["refs"].items()},
            "marks": reg["marks"], "banned_props": reg["banned_props"], "key_ref_props": reg["key_ref_props"], "key_ref": reg["key_ref"],
            "cluck_caps": {n: c["cluck"] for n, c in reg["components"].items() if "cluck" in c},
            "staged": {n: reg["components"][n]["ships"] for n in staged(reg)}}


def views_schema(reg):
    return {"description": "An item's views[]: authored OpenUI Lang views, one per stage (render v2 P3.1 wires it into problems).",
            "type": "array",
            "items": {"type": "object", "additionalProperties": False, "required": ["stage", "recipe", "src"],
                      "properties": {"stage": {"type": "string", "pattern": "^(pre|post|wrong:[A-Za-z0-9_-]+)$"},
                                     "recipe": {"enum": list(reg["recipes"])},
                                     "src": {"type": "string", "minLength": 1},
                                     "lib": {"type": "string", "description": "library version the view was checked against"}}}}


def schema_block(reg):
    c = reg["components"]
    lines = [BEGIN,
             f"Library {reg['version']}, profile `{reg['profile']}`. Source: `views/registry.json`; regenerate with `python3 tools/gen_views.py`. "
             "Outputs: `views/library.json` (shipping components only), `views/prompt/*.md`, `views/checkers.json`, this block. "
             "Args show caps: `string≤N` characters, `[]≤N` items. No look props (F3); look = CSS by cascade.", "",
             "Marks (the only state words): " + ", ".join(f"`{m}`" for m in reg["marks"]) + ". Banned prop names: "
             + ", ".join(f"`{p}`" for p in reg["banned_props"]) + ". " + " or ".join(f"`{p}`" for p in reg["key_props"]) + " may name a prop only as "
             + ", ".join(f"`{p}`" for p in reg["key_ref_props"]) + f", a required key reference (`{reg['key_ref']}`), never a literal.", "",
             "| Ref | Allowed stages | What |", "|---|---|---|"]
    lines += [f"| `{r}.*` | {', '.join(d['stages'])} | {d['desc']} |" for r, d in reg["refs"].items()]
    lines += ["", "| Component | Layer | Kind | Ships | Args | Checker |", "|---|---|---|---|---|---|"]
    lines += [f"| {n} | {x['layer']} | {x['kind']} | {x['ships']} | `{sig(reg, n, caps=True, pool=pool(reg))}` | {x.get('checker', '')} |" for n, x in c.items()]
    lines += ["", "| Recipe | Stages | Length | Components |", "|---|---|---|---|"]
    lines += [f"| {r} | {', '.join(x['stages'])} | {x['length']} | {', '.join(x['components'])} |" for r, x in reg["recipes"].items()]
    lines += ["", "| Engine | Ships | Tools |", "|---|---|---|"]
    lines += [f"| {e} | {x['ships']} | {', '.join(x['tools'])} |" for e, x in reg["engines"].items()]
    lines += ["", "<!-- schema: views -->", "```json", json.dumps(views_schema(reg), indent=2), "```", END]
    return "\n".join(lines)


def outputs(reg, schema_md):
    """{path: text} for every generated file. schema_md = current SCHEMA.md text (must hold the markers)."""
    i, j = schema_md.find(BEGIN), schema_md.find(END)
    if i < 0 or j < i:
        raise SystemExit(f"SCHEMA.md: views markers missing ({BEGIN} … {END})")
    dump = lambda o: json.dumps(o, indent=2, ensure_ascii=False) + "\n"
    out = {os.path.join(ROOT, "views", "library.json"): dump(library(reg)),
           os.path.join(ROOT, "views", "checkers.json"): dump(checkers(reg)),
           os.path.join(ROOT, "views", "prompt", "all.md"): prompt(reg),
           SCHEMA_MD: schema_md[:i] + schema_block(reg) + schema_md[j + len(END):]}
    for r in reg["recipes"]:
        out[os.path.join(ROOT, "views", "prompt", r + ".md")] = prompt(reg, r)
    return out


def main(argv):
    reg = load()
    bad = problems(reg, engine_tools())
    if bad:
        print("\n".join(bad), file=sys.stderr)
        return 1
    with open(SCHEMA_MD) as f:
        out = outputs(reg, f.read())
    stale = []
    for path, text in out.items():
        try:
            with open(path) as f:
                same = f.read() == text
        except OSError:
            same = False
        if same:
            continue
        stale.append(os.path.relpath(path, ROOT))
        if "--check" not in argv:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w") as f:
                f.write(text)
    if "--check" in argv and stale:
        print("stale (run python3 tools/gen_views.py): " + ", ".join(stale), file=sys.stderr)
        return 1
    print("wrote " + ", ".join(stale) if stale else "up to date")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
